import { readFile } from "node:fs/promises";
import { checkpoint, restore } from "@tigrisdata/agent-kit";
import { put } from "@tigrisdata/storage";

async function main() {
  const trialIdRaw = await readFile("/logs/artifacts/trial_id", "utf-8");
  const trialId = trialIdRaw.trim().toLowerCase().replace(/[^a-z0-9.-]/g, "-");

  const baseBucket = `harbor-base-${trialId}`;
  const forkBucket = `harbor-restore-${trialId}`;

  console.log(`Base bucket: ${baseBucket}`);
  console.log(`Fork bucket: ${forkBucket}`);

  // Step A: Checkpoint
  console.log("Taking checkpoint...");
  const { data: ckpt, error: ckptErr } = await checkpoint(baseBucket, { name: "before-eval" });
  if (ckptErr) throw ckptErr;
  const snapshotId = ckpt.snapshotId;
  console.log(`Checkpoint taken: ${snapshotId}`);

  // Step B: Write data/v3.txt to base bucket
  console.log("Writing data/v3.txt...");
  const { error: putErr } = await put("data/v3.txt", "version3", {
    config: { bucket: baseBucket },
    contentType: "text/plain",
  });
  if (putErr) throw putErr;
  console.log("Wrote data/v3.txt");

  // Step C: Restore checkpoint to fork bucket
  console.log("Restoring checkpoint...");
  const { data: restored, error: restoreErr } = await restore(baseBucket, snapshotId, {
    forkName: forkBucket,
  });
  if (restoreErr) throw restoreErr;
  if (restored.bucket !== forkBucket) {
    throw new Error(`unexpected restored bucket: ${restored.bucket}`);
  }
  console.log(`Restored to fork bucket: ${restored.bucket}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

