import { readFile } from "node:fs/promises";
import { createBucket, put } from "@tigrisdata/storage";

async function main() {
  const trialIdRaw = await readFile("/logs/artifacts/trial_id", "utf-8");
  const trialId = trialIdRaw.trim().toLowerCase().replace(/[^a-z0-9.-]/g, "-");
  const baseBucket = `harbor-base-${trialId}`;

  console.log(`Creating bucket: ${baseBucket}`);
  const { data: createData, error: createErr } = await createBucket(baseBucket, { enableSnapshot: true });
  if (createErr) {
    if (createErr.message.includes("already exists") || createErr.message.includes("BucketAlreadyExists")) {
      console.log("Bucket already exists.");
    } else {
      throw createErr;
    }
  } else {
    console.log("Bucket created:", createData);
  }

  console.log("Putting data/v1.txt...");
  const { error: put1Err } = await put("data/v1.txt", "version1", { config: { bucket: baseBucket }, contentType: "text/plain" });
  if (put1Err) throw put1Err;

  console.log("Putting data/v2.txt...");
  const { error: put2Err } = await put("data/v2.txt", "version2", { config: { bucket: baseBucket }, contentType: "text/plain" });
  if (put2Err) throw put2Err;

  console.log("Setup complete.");
}

main().catch(err => {
  console.error("Setup failed:", err);
  process.exit(1);
});
